```python
def transform(grid):
    from collections import defaultdict
    H = len(grid); W = len(grid[0])
    g = [row[:] for row in grid]
    counts = defaultdict(int)
    for r in grid:
        for v in r:
            counts[v] += 1
    bg = max(counts, key=lambda k: counts[k])
    cells = defaultdict(list)
    for r in range(H):
        for c in range(W):
            cells[g[r][c]].append((r, c))
    dirs_main = [(-1, -1), (1, 1)]
    dirs_anti = [(-1, 1), (1, -1)]
    for color, pts in cells.items():
        if color == bg or len(pts) < 2:
            continue
        for keyf, dirs in ((lambda r, c: r - c, dirs_main), (lambda r, c: r + c, dirs_anti)):
            groups = defaultdict(list)
            for r, c in pts:
                groups[keyf(r, c)].append((r, c))
            for k, grp in groups.items():
                if len(grp) < 2:
                    continue
                for (r, c) in grp:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        while 0 <= nr < H and 0 <= nc < W and g[nr][nc] == bg:
                            g[nr][nc] = color
                            nr += dr; nc += dc
    return g
